import { getElement } from '../../utils/functional';
const classes = {
  activeDrawerClass: 'drw-Drawer-active'
};
export class Drawer {
  constructor(key, drawers) {
    this.key = key;
    this.drawers = drawers;
    this._isOpen = false;

    if (this.drawerShouldBeMoved) {
      this.moveToElement.appendChild(this.els.drawer);
    }
  }

  get els() {
    return {
      trigger: getElement("[data-module-drawers-trigger=".concat(this.key, "]")),
      drawer: getElement("[data-module-drawers-drawer=".concat(this.key, "]")),
      close: getElement("[data-module-drawers-close=".concat(this.key, "]"))
    };
  }

  get isOpen() {
    return this._isOpen;
  }

  set isOpen(val) {
    this._isOpen = val;
    this.els.drawer.classList.toggle(classes.activeDrawerClass, val);
  }

  get drawerShouldBeMoved() {
    return this.els.drawer.hasAttribute('data-module-drawers-move-me');
  }

  get moveToElement() {
    if (this.els.drawer.getAttribute('data-module-drawers-move-me') === 'root') {
      return this.drawers.element;
    }
  }

}